const cloudWords={account:['Hesabım','Hesabım','Мой аккаунт','My account','حسابي'],admin:['Tətbiq idarəetməsi','Uygulama yönetimi','Управление приложением','App administration','إدارة التطبيق'],signin:['Daxil ol','Giriş yap','Войти','Sign in','تسجيل الدخول'],signup:['Qeydiyyat','Kayıt ol','Регистрация','Sign up','إنشاء حساب'],signout:['Çıxış','Çıkış','Выйти','Sign out','تسجيل الخروج'],email:['E-poçt','E-posta','Эл. почта','Email','البريد الإلكتروني'],password:['Şifrə','Şifre','Пароль','Password','كلمة المرور'],name:['Adınız','Adınız','Ваше имя','Your name','اسمك'],save:['Saxla','Kaydet','Сохранить','Save','حفظ'],checkMail:['Təsdiq keçidi üçün e-poçtunuzu yoxlayın.','Onay bağlantısı için e-postanızı kontrol edin.','Проверьте почту для подтверждения.','Check your email for the confirmation link.','تحقق من بريدك للحصول على رابط التأكيد.'],offline:['Bulud bağlantısı hazır deyil. Yerli funksiyalar işləməyə davam edir.','Bulut bağlantısı hazır değil. Yerel özellikler çalışmaya devam eder.','Облако недоступно. Локальные функции продолжают работать.','Cloud unavailable. Local features remain available.','السحابة غير متاحة. الميزات المحلية مستمرة.'],backup:['Ehtiyat nüsxə','Yedekleme','Резервная копия','Backup','نسخة احتياطية'],backupNote:['Şəxsi dua və qeydləriniz yalnız öz hesabınıza bağlı şifrəli HTTPS bağlantısı ilə buluda göndəriləcək. Admin şəxsi mətnləri görə bilməz. Bu seçim məcburi deyil.','Kişisel dualarınız ve kayıtlarınız HTTPS ile yalnız hesabınıza bağlı buluta yüklenir. Yönetici özel metinleri göremez. İsteğe bağlıdır.','Личные дуа и записи передаются по HTTPS в ваше облако. Администратор не видит личные тексты. Необязательно.','Private duas and records are sent over HTTPS to your own account storage. Admins cannot read private texts. Optional.','تُنقل أدعيتك وسجلاتك عبر HTTPS إلى مساحة حسابك. لا يقرأ المشرف النصوص الخاصة. اختياري.'],consent:['Şəxsi qeydlərimi buluda göndərməyə razıyam','Kişisel kayıtlarımı buluta göndermeyi kabul ediyorum','Согласен отправить личные записи в облако','I agree to upload my private records','أوافق على رفع سجلاتي الخاصة'],upload:['Buluda saxla','Buluta kaydet','Сохранить в облако','Save to cloud','حفظ في السحابة'],restore:['Bu cihazda bərpa et','Bu cihazda geri yükle','Восстановить на устройстве','Restore on this device','استعادة على هذا الجهاز'],restoreWarn:['Bu cihazdakı uyğun qeydlər bulud nüsxəsi ilə əvəz edilsin?','Bu cihazdaki ilgili kayıtlar bulut kopyasıyla değiştirilsin mi?','Заменить записи устройства облачной копией?','Replace matching local records with the cloud backup?','استبدال سجلات الجهاز المطابقة بالنسخة السحابية؟'],required:['Bütün sahələri düzgün doldurun. Şifrə ən az 10 simvol olsun.','Tüm alanları doldurun. Şifre en az 10 karakter olmalı.','Заполните поля. Пароль не менее 10 символов.','Fill the fields. Password must be at least 10 characters.','أكمل الحقول. كلمة المرور ١٠ أحرف على الأقل.'],saved:['Saxlanıldı','Kaydedildi','Сохранено','Saved','تم الحفظ'],denied:['Hesabınızın bulud girişinə məhdudiyyət qoyulub.','Hesabınızın bulut erişimi kısıtlandı.','Облачный доступ ограничен.','Cloud access is restricted for this account.','الوصول السحابي لهذا الحساب مقيد.'],error:['Sorğu tamamlanmadı. Bağlantını və hesab məlumatlarını yoxlayın.','İstek tamamlanamadı. Bağlantıyı ve hesap bilgilerini kontrol edin.','Ошибка запроса. Проверьте подключение и данные.','Request failed. Check your connection and account details.','تعذر الطلب. تحقق من الاتصال وبيانات الحساب.'],empty:['Hələ qeyd yoxdur','Henüz kayıt yok','Записей пока нет','No records yet','لا توجد سجلات بعد'],reset:['Şifrəni unutdum','Şifremi unuttum','Забыл пароль','Forgot password','نسيت كلمة المرور'],history:['Fəaliyyət tarixçəm','Etkinlik geçmişim','История действий','My activity','سجل نشاطي']};
cloudWords.registrationNote=["Qeydiyyatdan sonra dərhal hesabına daxil olub təklif yaza bilərsən.","Kayıttan sonra hemen giriş yapıp öneri yazabilirsin.","После регистрации можно сразу войти и оставить идею.","Sign in immediately after registration to share an idea.","يمكنك الدخول فور التسجيل ومشاركة فكرة."];
function cw(k){return cloudWords[k]?.[['az','tr','ru','en','ar'].indexOf(lang())]||cloudWords[k]?.[0]||k}
let cloudState={session:null,profile:null,admin:false,loading:false,error:'',content:[],events:[],backup:null,recovering:false},cloudMode='signin',cloudAdminData=null,cloudEditId=null;
const cloudBackupKeys=['nur-records','nur-fasts','nur-guide','nur-settings','basira-profile','basira-tasbih','basira-theme','basira-language','shams-dua-book','shams-quiz','shams-names','shams-fast-journal'];
function cloudConfigured(){return !!(SHAMS_CLOUD_CONFIG.url.startsWith('https://')&&SHAMS_CLOUD_CONFIG.key)}
function cloudStoreSession(session){cloudState.session=session?{access_token:session.access_token,refresh_token:session.refresh_token,expires_at:Math.floor(Date.now()/1000)+(session.expires_in||3600),user:session.user}:null;if(cloudState.session)safeWrite('shams-cloud-session',cloudState.session);else localStorage.removeItem('shams-cloud-session')}
async function cloudRequest(path,body,method=body===undefined?'GET':'POST',retry=true){if(!cloudConfigured())throw Error(cw('offline'));const token=cloudState.session?.access_token;const r=await fetch(SHAMS_CLOUD_CONFIG.url+path,{method,headers:{apikey:SHAMS_CLOUD_CONFIG.key,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{}),...(method==='PATCH'?{Prefer:'return=representation'}:{})},...(body===undefined?{}:{body:JSON.stringify(body)}),signal:AbortSignal.timeout(20000)});if(r.status===401&&retry&&cloudState.session?.refresh_token){await cloudRefresh();return cloudRequest(path,body,method,false)}if(!r.ok)throw Error(cw('error'));return r.status===204?null:r.json()}
async function cloudRefresh(){const s=cloudState.session;if(!s?.refresh_token)throw Error(cw('error'));const r=await fetch(SHAMS_CLOUD_CONFIG.url+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:SHAMS_CLOUD_CONFIG.key,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:s.refresh_token})});if(!r.ok){cloudStoreSession(null);throw Error(cw('error'))}cloudStoreSession(await r.json())}
function cloudPaint(){if(['account','cloudadmin'].includes(location.hash.slice(1).split('/')[0])&&!document.querySelector('.modal-layer'))render()}
async function loadCloudProfile(){if(!cloudState.session)return;const user=await cloudRequest('/auth/v1/user',undefined,'GET',false);cloudState.session.user=user;const profiles=await cloudRequest('/rest/v1/shams_profiles?id=eq.'+encodeURIComponent(user.id)+'&select=*');cloudState.profile=profiles[0]||null;if(cloudState.profile?.display_name&&!personalProfile().name){const p=personalProfile();p.name=cloudState.profile.display_name;save('basira-profile',p)}cloudState.admin=await cloudRequest('/rest/v1/rpc/shams_claim_admin',{});if(!cloudState.admin)cloudState.admin=await cloudRequest('/rest/v1/rpc/shams_is_admin',{});if(cloudState.profile?.disabled){cloudState.error=cw('denied');cloudState.admin=false}cloudState.events=await cloudRequest('/rest/v1/shams_events?select=kind,details,created_at&order=created_at.desc&limit=20');const backups=await cloudRequest('/rest/v1/shams_backups?select=revision,updated_at&limit=1');cloudState.backup=backups[0]||null}
async function cloudAuth(form){if(cloudState.loading)return;const f=new FormData(form),email=String(f.get('email')||'').trim(),password=String(f.get('password')||''),display_name=String(f.get('name')||'').trim().slice(0,80);if(!email||password.length<10)return toast(cw('required'));cloudState.loading=true;cloudState.error='';try{const redirect=encodeURIComponent(SHAMS_PUBLIC_URL),data=await cloudRequest(cloudMode==='signup'?'/auth/v1/signup?redirect_to='+redirect:'/auth/v1/token?grant_type=password',cloudMode==='signup'?{email,password,data:{display_name}}:{email,password},'POST',false);if(data.access_token){cloudStoreSession(data);await loadCloudProfile();if(display_name){const profile=personalProfile();profile.name=display_name;save('basira-profile',profile)}toast(cw('saved'))}else toast(cw('checkMail'));form.reset()}catch(e){cloudState.error=e.message}finally{cloudState.loading=false;cloudPaint()}}
async function cloudLogout(){try{await cloudRecord('signed_out');await cloudRequest('/auth/v1/logout',{})}catch{}cloudStoreSession(null);cloudState.profile=null;cloudState.error='';cloudState.admin=false;cloudAdminData=null;cloudState.events=[];cloudPaint()}
async function cloudResetPassword(form){const email=form.elements.email.value.trim();if(!email)return toast(cw('required'));try{await cloudRequest('/auth/v1/recover?redirect_to='+encodeURIComponent(SHAMS_PUBLIC_URL),{email},'POST',false);toast(cw('checkMail'))}catch(e){toast(e.message)}}
async function cloudSetPassword(form){const password=form.elements.password.value;if(password.length<10)return toast(cw('required'));try{await cloudRequest('/auth/v1/user',{password},'PUT');cloudState.recovering=false;toast(cw('saved'));cloudPaint()}catch(e){toast(e.message)}}
async function cloudRecord(kind,count=0){if(!cloudState.session||cloudState.profile?.disabled)return;try{await cloudRequest('/rest/v1/rpc/shams_record_event',{p_kind:kind,p_count:Math.min(1000000,Math.max(0,count))})}catch{}}
async function cloudSaveName(form){const display_name=form.elements.display_name.value.trim().slice(0,80);try{await cloudRequest('/rest/v1/shams_profiles?id=eq.'+cloudState.session.user.id,{display_name,locale:lang()},'PATCH');const p=personalProfile();p.name=display_name;save('basira-profile',p);await loadCloudProfile();cloudPaint();toast(cw('saved'))}catch(e){toast(e.message)}}
async function cloudUploadBackup(form){if(!form.elements.consent.checked)return;const snapshot={version:1,data:{}};for(const k of cloudBackupKeys){const raw=localStorage.getItem(k);if(raw!==null)try{snapshot.data[k]=JSON.parse(raw)}catch{}}try{const revision=await cloudRequest('/rest/v1/rpc/shams_save_backup',{p_snapshot:snapshot,p_revision:cloudState.backup?.revision||0});cloudState.backup={revision,updated_at:new Date().toISOString()};cloudPaint();toast(cw('saved'))}catch(e){toast(e.message)}}
async function cloudRestoreBackup(){if(!window.confirm(cw('restoreWarn')))return;try{const rows=await cloudRequest('/rest/v1/shams_backups?select=snapshot,revision,updated_at&limit=1'),snapshot=rows[0]?.snapshot;if(!snapshot||snapshot.version!==1||!snapshot.data)throw Error(cw('empty'));for(const k of cloudBackupKeys)if(Object.hasOwn(snapshot.data,k))safeWrite(k,snapshot.data[k]);await cloudRecord('backup_restored');location.reload()}catch(e){toast(e.message)}}
function accountPage(){const s=cloudState,profile=s.profile;return `<div data-localized="true" class="cloud-account">${head(cw('account'),'')}${s.error?`<p class="notice error" role="alert">${esc(s.error)}</p>`:''}${!cloudConfigured()?`<p class="card">${cw('offline')}</p>`:!s.session?`<div class="tabs"><button class="${cloudMode==='signin'?'active':''}" onclick="cloudMode='signin';render()">${cw('signin')}</button><button class="${cloudMode==='signup'?'active':''}" onclick="cloudMode='signup';render()">${cw('signup')}</button></div>${cloudMode==='signup'&&!SHAMS_CLOUD_CONFIG.registrationReady?`<p class="notice">${cw('registrationNote')}</p>`:''}<form class="card cloud-form" onsubmit="event.preventDefault();cloudAuth(this)">${cloudMode==='signup'?`<label>${cw('name')}<input name="name" maxlength="80" autocomplete="given-name" required></label>`:''}<label>${cw('email')}<input name="email" type="email" autocomplete="email" required></label><label>${cw('password')}<input name="password" type="password" minlength="10" autocomplete="${cloudMode==='signup'?'new-password':'current-password'}" required></label><button class="goldbtn" ${s.loading?'disabled':''}>${cw(cloudMode)}</button><button class="textbtn" type="button" onclick="cloudResetPassword(this.form)">${cw('reset')}</button></form>`:`<section class="card"><h2>${esc(profile?.display_name||s.session.user?.email||'SHAMS')}</h2><p class="muted">${esc(s.session.user?.email||'')}</p>${s.admin?`<button class="goldbtn wide" onclick="go('cloudadmin')">${cw('admin')} ↗</button>`:''}${s.recovering?`<form class="cloud-form" onsubmit="event.preventDefault();cloudSetPassword(this)"><label>${cw('password')}<input name="password" type="password" minlength="10" autocomplete="new-password" required></label><button class="goldbtn">${cw('save')}</button></form>`:`<form class="cloud-form" onsubmit="event.preventDefault();cloudSaveName(this)"><label>${cw('name')}<input name="display_name" maxlength="80" value="${esc(profile?.display_name||'')}"></label><button class="secondarybtn">${cw('save')}</button></form>`}<button class="textbtn" onclick="cloudLogout()">${cw('signout')}</button></section>${profile?.disabled?'':`<section class="card"><h2>${cw('backup')}</h2><p class="notice">${cw('backupNote')}</p><p>${esc(s.backup?.updated_at||'—')}</p><form class="cloud-form" onsubmit="event.preventDefault();cloudUploadBackup(this)"><label class="cloud-consent"><input type="checkbox" name="consent" required><span>${cw('consent')}</span></label><button class="goldbtn">${cw('upload')}</button></form><button class="secondarybtn wide" onclick="cloudRestoreBackup()" ${s.backup?'':'disabled'}>${cw('restore')}</button></section>`}<details class="card"><summary>${cw('history')}</summary>${s.events.map(e=>`<p>${esc(e.kind)} · ${esc(new Date(e.created_at).toLocaleString(lang()))}</p>`).join('')||cw('empty')}</details>`}</div>`}
async function loadCloudAdmin(){if(!cloudState.admin)return;try{cloudAdminData=await cloudRequest('/rest/v1/rpc/shams_admin_overview',{});if(route==='cloudadmin')render()}catch(e){toast(e.message)}}
function cloudAdminPage(){if(!cloudState.admin)return `<div data-localized="true">${head(cw('admin'),'')}<section class="card"><p>${cw('signin')}</p><button class="goldbtn" onclick="go('account')">${cw('account')} →</button></section></div>`;if(!cloudAdminData){setTimeout(loadCloudAdmin,0);return head(cw('admin'),'')+'<p>…</p>'}const d=cloudAdminData;return `<div class="cloud-admin" data-localized="true">${head(cw('admin'),'')}<div class="module-actions"><button class="secondarybtn" onclick="loadCloudAdmin()">↻ Yenilə</button><button class="goldbtn" onclick="editCloudContent()">＋ Məzmun</button></div><div class="module-stats"><div><b>${d.total_users}</b><span>Qeydiyyat</span></div><div><b>${d.disabled_users}</b><span>Məhdud hesab</span></div><div><b>${d.content.length}</b><span>Məzmun</span></div></div><details class="card" open><summary>İstifadəçilər və qeydiyyat tarixçəsi</summary><input type="search" placeholder="E-poçt və ya ad" oninput="filterCloudAdminUsers(this.value)"><div id="cloudAdminUsers">${cloudAdminUsersHTML('')}</div><p class="notice">Son 500 qeyd. Şəxsi dua mətnləri və ehtiyat nüsxələri adminə göstərilmir.</p></details><details class="card"><summary>Əlavələr və fəaliyyətlər</summary>${d.events.map(e=>`<div class="cloud-log"><strong>${esc(e.kind)}</strong><span>${esc(d.profiles.find(p=>p.id===e.user_id)?.email||'—')}</span><small>${esc(e.created_at)} · ${Number(e.details?.count)||0}</small></div>`).join('')||cw('empty')}</details><details class="card"><summary>Tətbiqin dua və elanları</summary>${d.content.map(c=>`<button class="row" onclick="editCloudContent('${c.id}')"><strong class="grow">${esc(c.payload.title)}</strong><span>${c.published?'●':'○'} ${esc(c.kind)}</span></button>`).join('')||cw('empty')}</details><details class="card"><summary>Admin audit tarixçəsi</summary>${d.audit.map(a=>`<p>${esc(a.action)} · ${esc(a.target)}<small>${esc(a.created_at)}</small></p>`).join('')||cw('empty')}</details></div>`}
function cloudAdminUsersHTML(query){const q=query.toLowerCase();return cloudAdminData.profiles.filter(p=>(p.email+' '+p.display_name).toLowerCase().includes(q)).map(p=>`<article class="cloud-user"><strong>${esc(p.display_name||p.email)} ${p.is_admin?'✦':''}</strong><small>${esc(p.email)}</small><small>Qeydiyyat: ${esc(p.created_at)}<br>Son giriş: ${esc(p.last_sign_in_at||'—')}</small>${p.id===cloudState.session.user.id?'':`<button class="secondarybtn" onclick="toggleCloudUser('${p.id}',${!p.disabled})">${p.disabled?'Girişi bərpa et':'Bulud girişini məhdudlaşdır'}</button>`}</article>`).join('')||cw('empty')}
function filterCloudAdminUsers(value){document.querySelector('#cloudAdminUsers').innerHTML=cloudAdminUsersHTML(value)}
async function toggleCloudUser(id,disabled){try{await cloudRequest('/rest/v1/rpc/shams_admin_user',{p_id:id,p_disabled:disabled});await loadCloudAdmin()}catch(e){toast(e.message)}}
function editCloudContent(id=null){cloudEditId=id;const c=cloudAdminData?.content.find(c=>c.id===id),p=c?.payload||{};showContentModal(modalHeading('Tətbiq məzmunu')+`<form class="cloud-form" onsubmit="event.preventDefault();saveCloudContent(this)"><label>Növ<select name="kind"><option value="dua" ${c?.kind==='dua'?'selected':''}>Dua</option><option value="announcement" ${c?.kind==='announcement'?'selected':''}>Elan</option></select></label><label>Dil<select name="locale">${['az','tr','ru','en','ar'].map(l=>`<option value="${l}" ${p.locale===l?'selected':''}>${l}</option>`).join('')}</select></label><label>Başlıq<input name="title" maxlength="160" required value="${esc(p.title||'')}"></label><label>Mətn / məna<textarea name="body" maxlength="12000" required>${esc(p.body||'')}</textarea></label><label>Ərəb mətni<textarea name="arabic" dir="rtl" maxlength="10000">${esc(p.arabic||'')}</textarea></label><label>Mənbə HTTPS<input name="source" type="url" value="${esc(p.source||'')}"></label><label><input type="checkbox" name="reviewed" ${p.reviewed?'checked':''}>Mənbə və mətn yoxlanılıb</label><label><input type="checkbox" name="published" ${c?.published?'checked':''}>Tətbiqdə yayımla</label><button class="goldbtn">Saxla</button></form>`)}
async function saveCloudContent(form){const f=new FormData(form),payload={title:String(f.get('title')||'').trim(),body:String(f.get('body')||'').trim(),arabic:String(f.get('arabic')||'').trim(),source:String(f.get('source')||'').trim(),locale:String(f.get('locale')),reviewed:f.get('reviewed')==='on'};try{await cloudRequest('/rest/v1/rpc/shams_admin_content',{p_id:cloudEditId,p_kind:f.get('kind'),p_payload:payload,p_published:f.get('published')==='on'});closeContentModal();await loadCloudAdmin();await loadCloudContent();toast(cw('saved'))}catch(e){toast(e.message)}}
async function loadCloudContent(){try{cloudState.content=await cloudRequest('/rest/v1/shams_content?published=eq.true&select=id,public_id,kind,payload,updated_at&order=updated_at.desc');if(['duas','collection','more'].includes(route)&&!document.querySelector('.modal-layer'))render()}catch{}}
const cloudOriginalDuas=allDuas;allDuas=function(){return [...cloudOriginalDuas(),...cloudState.content.filter(c=>c.kind==='dua'&&c.payload.reviewed===true&&typeof c.payload.title==='string'&&typeof c.payload.body==='string'&&/^https:\/\//.test(c.payload.source||'')&&(!c.payload.locale||c.payload.locale===lang())).map(c=>({id:1000000+c.public_id,title:c.payload.title,allTitles:[c.payload.title],subtitle:'SHAMS',arabic:c.payload.arabic||'',translit:'',meaning:c.payload.body,source:c.payload.source||'',sourceUrl:c.payload.source||''}))]};
function initializeCloud(){const originalMore=more;more=function(){return originalMore()+cloudAnnouncementsHTML()};for(const [r,i,t]of [['account','◎',cw('account')],['cloudadmin','⚙',cw('admin')]])if(!extra.some(x=>x[0]===r))extra.push([r,i,t]);if(!cloudConfigured())return;setTimeout(async()=>{cloudState.session=read('shams-cloud-session',null);const fragment=new URLSearchParams(location.hash.slice(1));if(fragment.has('access_token')){cloudStoreSession({access_token:fragment.get('access_token'),refresh_token:fragment.get('refresh_token'),expires_in:Number(fragment.get('expires_in'))||3600});cloudState.recovering=fragment.get('type')==='recovery';history.replaceState(null,'',location.pathname+location.search+'#account')}try{if(cloudState.session){if(cloudState.session.expires_at<Date.now()/1000+60)await cloudRefresh();await loadCloudProfile()}}catch{cloudState.error=cw('error');cloudStoreSession(null)}await loadCloudContent();cloudPaint()},0)}

const cloudSaveBookOriginal=saveBookForm;saveBookForm=function(form){const before=readDuaBook(),previous=before.entries.length;cloudSaveBookOriginal(form);const after=readDuaBook();if(after.revision>before.revision)cloudRecord(after.entries.length>previous?'dua_added':'dua_updated',after.entries.length)};
const cloudDeleteBookOriginal=deleteBookDua;deleteBookDua=function(id){const before=readDuaBook().entries.length;cloudDeleteBookOriginal(id);const after=readDuaBook().entries.length;if(after<before)cloudRecord('dua_deleted',after)};
const cloudQuizOriginal=advanceQuiz;advanceQuiz=function(){const before=quizStore().rounds.length;cloudQuizOriginal();const after=quizStore().rounds.length;if(after>before)cloudRecord('quiz_completed',1)};

moduleText.privacy=['Şəxsi dualar cihazda qalır. Hesabım bölməsində istəyə görə bulud ehtiyat nüsxəsi yarada bilərsiniz. Şəxsi mətnlər admin panelində göstərilmir.','Kişisel dualar cihazda kalır. Hesabım bölümünde isteğe bağlı bulut yedeği oluşturabilirsiniz. Özel metinler yönetim panelinde gösterilmez.','Личные дуа остаются на устройстве. В аккаунте можно добровольно сохранить облачную копию. Личные тексты не отображаются в админ-панели.','Personal duas stay on this device. You can optionally save a cloud backup from My account. Private texts are not shown in the admin panel.','تبقى الأدعية الخاصة على الجهاز. يمكنك حفظ نسخة سحابية اختياريًا من حسابي. لا تظهر النصوص الخاصة في لوحة الإدارة.'];

function cloudAnnouncementsHTML(){return cloudState.content.filter(c=>c.kind==='announcement'&&(!c.payload.locale||c.payload.locale===lang())).map(c=>`<section class="card" data-localized="true"><h3>${esc(c.payload.title)}</h3><p>${esc(c.payload.body)}</p></section>`).join('')}
